import csv
import statistics

rows = []
with open('records.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        qty = int(row['qty'])
        price = int(row['price'])
        if qty >= 3 and price < 15:
            rows.append(qty)

if not rows:
    print("")
else:
    median_val = statistics.median(rows)
    # Format: if integer, print as integer, else as float
    if median_val == int(median_val):
        print(int(median_val))
    else:
        print(median_val)
